            '<button type="button" role="option" data-code="en">English</button>' +
            '<button type="button" role="option" data-code="ja">\u65E5\u672C\u8A9E</button>' +
            '<button type="button" role="option" data-code="zh">\u4E2D\u6587</button>' +
            '<button type="button" role="option" data-code="es">Espa\u00F1ol</button>' +
            '</div>';
